from shipping import fee


def test_fee_for_range_boundaries():
    for amount_cents in (0, 9999):
        result = fee(amount_cents)
        assert isinstance(result, int)
        assert result == 1000

from shipping import fee


def test_fee_at_and_above_threshold():
    for amount_cents in (10000, 10001):
        result = fee(amount_cents)
        assert isinstance(result, int)
        assert result == 0

import pytest
from shipping import fee


def test_non_builtin_int_arguments_raise_type_error():
    for amount_cents in (1.0, True):
        with pytest.raises(TypeError):
            fee(amount_cents)

